-- edu-menu.sql
-- 教育域菜单种子数据：登录后左侧出现「教育管理」及其 12 个分组与 41 个页面
-- 事实源：docs/40-detailed-design/frontend-page-tree.yaml（45 条路由，41 条进侧栏；登录/403/404/500 是静态路由）
--         + apps/plus-ui/src/router/index.ts 的 dynamicRoutes（逐页权限点）
-- 结构：教育管理(M) → 分组(M,12) → 页面(C,41) → 按钮(F) ；id 区间 13000-13999（现有最大 menu_id=11806）
-- 幂等：先按 id 区间清理（含 sys_role_menu 关联）再插入；可重复执行
-- 注意：super_admin（role_id=1）由后端 selectMenuTreeAll() 直接放行，无需 sys_role_menu 授权；
--       其它角色请在「系统管理 → 角色管理」里勾选新增的这些菜单。

SET NAMES utf8mb4;
DELETE FROM `sys_role_menu` WHERE menu_id BETWEEN 13000 AND 13999;
DELETE FROM `sys_menu` WHERE menu_id BETWEEN 13000 AND 13999;

